class BobaCafe {
public:
    BobaCafe() : id(++num_created), bobaCooker(3), num_drinks_served(0) {
        // TODO: one more cafe is open
    }
    ~BobaCafe() {
        // TODO: this cafe is closing
    }
    Drink doOrder(const string& customer_name);
    int getId() const { return id; }
    int getDrinksServed() const { return num_drinks_served; }
    static int getNumOpen() { /* TODO */ return 0; }
    static int getTotalServed() { /* TODO */ return 0; }
private:
    static int num_created;
    static int num_open;
    static int total_served;
    const int id;
    OrderKiosk orderKiosk;
    TeaBrewer teaBrewer;
    BobaCooker bobaCooker;
    ToppingStation toppingStation;
    int num_drinks_served;
};

// each static data member is defined once, outside the class (normally in bobacafe.cpp)
int BobaCafe::num_created = 0;
int BobaCafe::num_open = 0;
int BobaCafe::total_served = 0;

Drink BobaCafe::doOrder(const string& customer_name) {
    Drink newDrink;
    orderKiosk.takeOrder(customer_name, newDrink);
    teaBrewer.addTea(newDrink);
    bobaCooker.addBoba(newDrink);
    toppingStation.addToppings(newDrink);
    num_drinks_served++;
    return newDrink;
}

#include "check.h"
#include "cafe.h"

int main() {
    {
        BobaCafe a;
        CHECK_EQ(BobaCafe::getNumOpen(), 1);
        a.doOrder("Customer 0");
        a.doOrder("Customer 1");
    }                                   // a closes here
    CHECK_EQ(BobaCafe::getNumOpen(), 0);
    CHECK_EQ(BobaCafe::getTotalServed(), 2);
    if (submitting()) {
        BobaCafe b;
        {
            BobaCafe c;
            CHECK_EQ(BobaCafe::getNumOpen(), 2);
            c.doOrder("Customer 2");
            CHECK_EQ(BobaCafe::getTotalServed(), 2);   // c hasn't closed yet
        }
        CHECK_EQ(BobaCafe::getNumOpen(), 1);
        CHECK_EQ(BobaCafe::getTotalServed(), 3);
        BobaCafe* p = new BobaCafe();
        CHECK_EQ(BobaCafe::getNumOpen(), 2);
        p->doOrder("Customer 3");
        delete p;
        CHECK_EQ(BobaCafe::getNumOpen(), 1);
        CHECK_EQ(BobaCafe::getTotalServed(), 4);
    }
    return check_done();
}

