#pragma once
#include <string>
using std::string;

// ---- done in earlier lessons ----

struct Drink {
    string customer_name;
    string tea_type;
    string boba_type;
    string topping_list;
};

class BobaCooker {
public:
    BobaCooker(int capacity) : capacity(capacity), servings_left(capacity), refill_count(0) {}
    int getCapacity() const { return capacity; }
    int getServingsLeft() const { return servings_left; }
    int getRefillCount() const { return refill_count; }
    bool setServingsLeft(int n);
    void addBoba(Drink& drink);
private:
    const int capacity;
    int servings_left;
    int refill_count;
};

bool BobaCooker::setServingsLeft(int n) {
    if (n < 0 || n > capacity) return false;
    servings_left = n;
    return true;
}

void BobaCooker::addBoba(Drink& drink) {
    if (servings_left == 0) {
        servings_left = capacity;
        refill_count++;
    }
    servings_left--;
    drink.boba_type = "Boba Pearls";
}

class OrderKiosk {
public:
    void takeOrder(const string& name, Drink& drink) { drink.customer_name = name; }
};

class TeaBrewer {
public:
    void addTea(Drink& drink) { drink.tea_type = "Black Tea"; }
};

class ToppingStation {
public:
    void addToppings(Drink& drink) { drink.topping_list = "Lychee Jelly"; }
};

class BobaCafe {
public:
    BobaCafe() : id(++num_created), bobaCooker(3), num_drinks_served(0) {
        num_open++;
    }
    ~BobaCafe() {
        num_open--;
        total_served += num_drinks_served;
    }
    Drink doOrder(const string& customer_name);
    int getId() const { return id; }
    int getDrinksServed() const { return num_drinks_served; }
    static int getNumOpen() { return num_open; }
    static int getTotalServed() { return total_served; }
private:
    static int num_created;
    static int num_open;
    static int total_served;
    const int id;
    OrderKiosk orderKiosk;
    TeaBrewer teaBrewer;
    BobaCooker bobaCooker;
    ToppingStation toppingStation;
    int num_drinks_served;
};

// each static data member is defined once, outside the class (normally in bobacafe.cpp)
int BobaCafe::num_created = 0;
int BobaCafe::num_open = 0;
int BobaCafe::total_served = 0;

Drink BobaCafe::doOrder(const string& customer_name) {
    Drink newDrink;
    orderKiosk.takeOrder(customer_name, newDrink);
    teaBrewer.addTea(newDrink);
    bobaCooker.addBoba(newDrink);
    toppingStation.addToppings(newDrink);
    num_drinks_served++;
    return newDrink;
}

// ---- this lesson ----

class MobileBobaCafe : public BobaCafe {
public:
    MobileBobaCafe() : BobaCafe(), propane_remaining(15.0f) {}
    float getPropane() const { return propane_remaining; }
    bool addPropane(float amount);
    Drink doOrder(const string& customer_name);
private:
    float propane_remaining;
};

bool MobileBobaCafe::addPropane(float amount) {
    if (amount <= 0) return false;
    propane_remaining += amount;
    return true;
}

Drink MobileBobaCafe::doOrder(const string& customer_name) {
    if (propane_remaining <= 1.0f) return Drink();
    propane_remaining -= 1.0f;
    return BobaCafe::doOrder(customer_name);
}

