class IntArray {
public:
    IntArray(int n) : data(new int[n]()), n(n) {}
    ~IntArray() { delete[] data; }

    // ---- this lesson ----
    // BUG: shallow copy. Both objects end up sharing one array.
    IntArray(const IntArray& other) : data(other.data), n(other.n) {}

    int& operator[](int i) { return data[i]; }
    int size() const { return n; }

private:
    int* data;
    int n;
};

#include "check.h"
#include "intarray.h"

// Two objects sharing one array would delete it twice, so report it and stop before the destructors run.
void mustNotShare(IntArray& first, IntArray& second, const char* step) {
    if (first.size() == 0 || second.size() == 0 || &first[0] != &second[0]) return;
    std::cout << "✘ Fail  " << step << " made two objects share one array\n";
    ++check_fails();
    _exit(check_done());
}

int sumOf(IntArray copy) {      // by value: the copy constructor runs
    copy[0] = -1000;            // changes only the copy
    int s = 0;
    for (int i = 0; i < copy.size(); i++) s += copy[i];
    return s;
}

int main() {
    IntArray a(3);
    a[0] = 1; a[1] = 2; a[2] = 3;
    IntArray b = a;
    mustNotShare(a, b, "the copy constructor");
    a[0] = 99;
    CHECK_EQ(b[0], 1);          // b has its own array
    CHECK_EQ(b[2], 3);
    CHECK_EQ(b.size(), 3);
    if (submitting()) {
        CHECK_EQ(sumOf(a), -1000 + 2 + 3);
        CHECK_EQ(a[0], 99);     // passing by value left a alone
        IntArray c(b);
        mustNotShare(b, c, "IntArray c(b)");
        c[1] = 50;
        CHECK_EQ(b[1], 2);
        IntArray e(0);
        IntArray f = e;
        CHECK_EQ(f.size(), 0);
    }
    return check_done();
}

