#include "check.h"
#include "intarray.h"

// Two objects sharing one array would delete it twice, so report it and stop before the destructors run.
void mustNotShare(IntArray& first, IntArray& second, const char* step) {
    if (first.size() == 0 || second.size() == 0 || &first[0] != &second[0]) return;
    std::cout << "✘ Fail  " << step << " made two objects share one array\n";
    ++check_fails();
    _exit(check_done());
}

int main() {
    IntArray a(3);
    a[0] = 1; a[1] = 2; a[2] = 3;
    IntArray c(1);              // too small: operator= must reallocate
    c = a;
    mustNotShare(a, c, "operator=");
    a[1] = 77;
    CHECK_EQ(c.size(), 3);
    CHECK_EQ(c[1], 2);
    CHECK_EQ(c[2], 3);
    if (submitting()) {
        IntArray& same = c;
        c = same;               // self-assignment must not destroy c
        CHECK_EQ(c[2], 3);
        IntArray big(6);
        big = a;                // bigger: still ends up with 3
        mustNotShare(a, big, "operator=");
        CHECK_EQ(big.size(), 3);
        CHECK_EQ(big[1], 77);
        IntArray d(2), e(5);
        d = e = c;              // chaining
        mustNotShare(d, e, "d = e = c");
        CHECK_EQ(d.size(), 3);
        CHECK_EQ(d[0], 1);
        const IntArray& back = (e = c);
        CHECK(&back == &e);     // returns *this, not a copy
    }
    return check_done();
}

