#include <csignal>
#include <string>
#include <sys/wait.h>
#include "check.h"
#include "myarray.h"

// Runs a[idx] on a 3-element myArray in a child process, and reports whether that called abort().
bool aborts(int idx) {
    pid_t pid = fork();
    if (pid == 0) {
        std::signal(SIGABRT, [](int) { _exit(42); });
        myArray<int> a(3);
        a[idx] = 7;
        _exit(0);
    }
    int status = 0;
    waitpid(pid, &status, 0);
    return WIFEXITED(status) && WEXITSTATUS(status) == 42;
}

int main() {
    myArray<int> beds(3);
    beds[0] = 2;
    beds[2] = 4;
    CHECK_EQ(beds[2], 4);
    CHECK_EQ(beds.size(), 3);
    myArray<std::string> names(2);
    names[1] = "CV2";
    CHECK_EQ(names[1], std::string("CV2"));
    if (submitting()) {
        beds[1] = beds[0] + beds[2];
        CHECK_EQ(beds[1], 6);
        CHECK_EQ(names.size(), 2);
        CHECK(aborts(-1));
        CHECK(aborts(3));
        CHECK(!aborts(2));
    }
    return check_done();
}

