#pragma once
#include <cstdlib>

template <typename T>
class myArray {
public:
    myArray(int size = 0);
    ~myArray();
    T& operator[](int idx);
    int size() const;

private:
    T* array;
    int allocated_size;
};

template <typename T>
myArray<T>::myArray(int size) : array(new T[size]), allocated_size(size) {}

template <typename T>
myArray<T>::~myArray() {
    delete[] array;
}

// ---- this lesson ----
template <typename T>
int myArray<T>::size() const {
    return allocated_size;
}

template <typename T>
T& myArray<T>::operator[](int idx) {
    if (idx < 0 || idx >= allocated_size) {
        abort();
    }
    return array[idx];
}

