#pragma once
#include <list>

int totalFree(const std::list<int>& beds) {
    int total = 0;
    for (std::list<int>::const_iterator it = beds.begin(); it != beds.end(); ++it)
        total += *it;
    return total;
}

void addBeds(std::list<int>& beds, int k) {
    for (auto& b : beds) b += k;
}

