int getMinVal(const vector<int>& v) {
    int minVal = v[0];
    for (int i = 1; i < (int)v.size(); i++) {
        if (v[i] < minVal) minVal = v[i];
    }
    return minVal;
}

void countingSort(vector<int>& v) {
    if (v.empty()) return;
    int minVal = getMinVal(v);
    int maxVal = getMaxVal(v);
    int range = maxVal - minVal + 1;
    vector<int> count(range, 0);
    for (int i = 0; i < (int)v.size(); i++) {
        count[v[i] - minVal]++;
    }
    int index = 0;
    for (int val = 0; val < range; val++) {
        for (int c = 0; c < count[val]; c++) {
            v[index] = val + minVal;
            index++;
        }
    }
}

