solution.growarray.h:
#pragma once

// A growable array that starts with room for 1 int.
class GrowArray {
public:
    GrowArray() : data(new int[1]), cap(1), n(0), copies(0) {}
    ~GrowArray() { delete[] data; }
    GrowArray(const GrowArray&) = delete;            // no copies in this lesson
    GrowArray& operator=(const GrowArray&) = delete;

    int size() const { return n; }
    int capacity() const { return cap; }
    long copyCount() const { return copies; }        // element copies made while growing
    int get(int i) const { return data[i]; }

    void push(int x) {
        if (n == cap) {
            int* bigger = new int[2 * cap];
            for (int i = 0; i < n; i++) {
                bigger[i] = data[i];
                copies++;
            }
            delete[] data;
            data = bigger;
            cap = 2 * cap;
        }
        data[n] = x;
        n++;
    }

private:
    int* data;
    int cap;
    int n;
    long copies;
};

