    deck.setHead(second);
    CHECK_EQ(toVector(deck.getHead()), vector<int>({2, 3, 4, 1}));
    CHECK(deck.getTail() == top);
    CHECK_EQ(deck.getCount(), 4);
    LinkedList same;
    for (int c : {2, 3, 4, 1}) same.append(c);
    CHECK(deck.equals(same));
    LinkedList different;
    for (int c : {2, 3, 1, 4}) different.append(c);
    CHECK(!deck.equals(different));
    if (submitting()) {
        LinkedList shorter;
        for (int c : {2, 3, 4}) shorter.append(c);
        CHECK(!deck.equals(shorter));
        CHECK(!shorter.equals(deck));
        LinkedList a, b;
        CHECK(a.equals(b));
        // Cut the deck down to its first two cards.
        Node* keep = deck.getHead()->next;
        Node* rest = keep->next;
        keep->next = nullptr;
        deck.setHead(deck.getHead());
        CHECK_EQ(deck.getCount(), 2);
        CHECK(deck.getTail() == keep);
        deck.append(9);
        CHECK_EQ(toVector(deck.getHead()), vector<int>({2, 3, 9}));
        while (rest) { Node* nx = rest->next; delete rest; rest = nx; }   // the cut-off cards are ours now
    }
    return check_done();
}

