#pragma once

struct Node {
    int elt;
    Node* next;
};

class LinkedList {
public:
    LinkedList() : head(nullptr), tail(nullptr), count(0) {}
    LinkedList(const LinkedList& other);          // deep copy
    LinkedList& operator=(const LinkedList&) = delete;   // Lab 4 didn't ask for it
    ~LinkedList();

    bool isEmpty() const { return count == 0; }
    int getCount() const { return count; }
    Node* getHead() const { return head; }
    Node* getTail() const { return tail; }

    void append(int v);
    void setHead(Node* newHead);
    bool equals(const LinkedList& other) const;

private:
    Node* head;
    Node* tail;
    int count;
};

// ---- done in earlier lessons ----

LinkedList::~LinkedList() {
    while (head != nullptr) {
        Node* nx = head->next;
        delete head;
        head = nx;
    }
}

void LinkedList::append(int v) {
    Node* n = new Node{v, nullptr};
    if (tail == nullptr) head = n;   // was empty: n is the first node too
    else tail->next = n;
    tail = n;
    count++;
}

LinkedList::LinkedList(const LinkedList& other) : LinkedList() {
    for (Node* p = other.head; p != nullptr; p = p->next) append(p->elt);
}

// ---- this lesson ----

void LinkedList::setHead(Node* newHead) {
    int len = 0;
    Node* lastNode = nullptr;
    head = newHead;
    while (newHead != nullptr) {
        lastNode = newHead;
        newHead = newHead->next;
        len++;
    }
    tail = lastNode;
    count = len;
}

bool LinkedList::equals(const LinkedList& other) const {
    if (count != other.count) return false;
    Node* mine = head;
    Node* theirs = other.head;
    while (mine != nullptr) {
        if (mine->elt != theirs->elt) return false;
        mine = mine->next;
        theirs = theirs->next;
    }
    return true;
}

