// Walks forward, so a cycle fails instead of hangs (capped).
vector<int> forward(DNode* h) { vector<int> v; for (; h && v.size() < 100; h = h->next) v.push_back(h->elt); return v; }
// True if every prev matches its next, the ends are nullptr, and tail is the last node.
bool consistent(DNode* head, DNode* tail) {
    if (head == nullptr || tail == nullptr) return head == tail;
    if (head->prev != nullptr || tail->next != nullptr) return false;
    DNode* p = head;
    for (int steps = 0; p != tail; steps++) {
        if (steps > 100 || p->next == nullptr || p->next->prev != p) return false;
        p = p->next;
    }
    return true;
