#pragma once

struct DNode {
    int elt;
    DNode* prev;
    DNode* next;
};

// given: the lecture's insertBack
void insertBack(DNode*& head, DNode*& tail, int v) {
    DNode* n = new DNode{v, tail, nullptr};
    if (tail != nullptr) tail->next = n;
    else head = n;   // was empty: n is the first node too
    tail = n;
}

void removeBack(DNode*& head, DNode*& tail) {
    if (tail == nullptr) return;
    DNode* old = tail;
    tail = tail->prev;
    if (tail != nullptr) tail->next = nullptr;
    else head = nullptr;   // now empty
    delete old;
}

void insertFront(DNode*& head, DNode*& tail, int v) {
    DNode* n = new DNode{v, nullptr, head};
    if (head != nullptr) head->prev = n;
    else tail = n;
    head = n;
}

void removeFront(DNode*& head, DNode*& tail) {
    if (head == nullptr) return;
    DNode* old = head;
    head = head->next;
    if (head != nullptr) head->prev = nullptr;
    else tail = nullptr;
    delete old;
}

