#include "check.h"
#include "tricks.h"
#include <vector>
using std::vector;

// The memory checker calls this on every heap allocation, so a set of visited nodes shows up here.
long allocations = 0;
extern "C" void __sanitizer_malloc_hook(const volatile void*, size_t) { ++allocations; }

vector<Node*> made;   // every node built here, so even a list with a cycle can be freed
Node* build(vector<int> v) {
    Node* h = nullptr;
    for (int i = (int)v.size() - 1; i >= 0; i--) { h = new Node{v[i], h}; made.push_back(h); }
    return h;
}

int main() {
    must_finish(5, "endless loop: does every pointer move forward, and does a cycle stop the loop?");
    Node* h = build({1, 2, 3});
    CHECK(!hasCycle(h));
    Node* c = build({1, 2, 3, 4, 5});
    Node* third = c->next->next;
    Node* fifth = third->next->next;
    fifth->next = third;             // 5 points back to 3
    CHECK(hasCycle(c));
    CHECK(fifth->next == third);     // the list is unchanged
    if (submitting()) {
        CHECK(!hasCycle(nullptr));
        CHECK(!hasCycle(build({1})));
        CHECK(!hasCycle(build({7, 7, 7, 7})));   // same values, no cycle
        Node* self = build({1});
        self->next = self;
        CHECK(hasCycle(self));
        Node* pair = build({1, 2});
        pair->next->next = pair;
        CHECK(hasCycle(pair));
        Node* lecture = build({1, 2, 5, 6, 7, 8, 9, 10});
        Node* six = lecture->next->next->next;
        Node* last = six;
        while (last->next) last = last->next;
        last->next = six;
        long before = allocations;
        bool found = hasCycle(lecture);
        bool noExtraMemory = allocations == before;
        CHECK(found);
        CHECK(noExtraMemory);   // O(1) space: nothing allocated
        CHECK(!hasCycle(build(vector<int>(100000, 1))));
    }
    for (Node* n : made) delete n;
    return check_done();
}

