bool hasCycle(Node* head) {
    Node* slow = head;
    Node* fast = head;
    while (fast != nullptr && fast->next != nullptr) {
        fast = fast->next->next;          // 1. the hare takes two steps
        if (fast == slow) return true;    // 2. caught the tortoise: cycle
        slow = slow->next;                // 3. the tortoise takes one step
    }
