#pragma once

struct Node {
    int elt;
    Node* next;
};

Node* interleave(Node* pile1, Node* pile2) {
    if (pile1 == nullptr) return pile2;
    Node* first = pile1;
    Node* last = pile1;        // the zipper: last node of the merged list
    pile1 = pile1->next;
    bool fromPile2 = true;
    while (pile1 != nullptr && pile2 != nullptr) {
        if (fromPile2) { last->next = pile2; pile2 = pile2->next; }
        else           { last->next = pile1; pile1 = pile1->next; }
        last = last->next;
        fromPile2 = !fromPile2;
    }
    last->next = (pile1 != nullptr) ? pile1 : pile2;   // the leftovers, in one step
    return first;
}

