// ---- this lesson ----

Node* faroShuffle(Node* deck, int count, bool inShuffle) {
    Node* pile1 = deck;
    Node* pile2 = deck;
    for (int i = 1; i < count / 2; i++) pile2 = pile2->next;
    // pile2 is now the card just before the cut
    Node* tmp = pile2->next;
    pile2->next = nullptr;
    pile2 = tmp;
    if (inShuffle) {   // the bottom half goes first
        pile2 = pile1;
        pile1 = tmp;
    }
    return interleave(pile1, pile2);
}

