#include "check.h"
#include "ops.h"
#include <map>
#include <set>
#include <vector>
using std::vector;

// Nodes built with build() are freed from this map, so relinking can't lose them.
std::map<Node*, int> made;
Node* build(vector<int> v) {
    Node* h = nullptr;
    for (int i = (int)v.size() - 1; i >= 0; i--) { h = new Node{v[i], h}; made[h] = v[i]; }
    return h;
}
bool relinkedOnly(Node* h) {   // only original nodes, with their original values
    for (int i = 0; h && i < 100; h = h->next, i++) {
        auto it = made.find(h);
        if (it == made.end() || it->second != h->elt) return false;
    }
    return true;
}
vector<int> toVector(Node* h, size_t cap = 100) {   // cap: a cycle must fail, not hang
    vector<int> v;
    for (; h && v.size() < cap; h = h->next) v.push_back(h->elt);
    return v;
}
// Lists the function may delete from are built with fresh() and freed with freeList().
Node* fresh(vector<int> v) { Node* h = nullptr; for (int i = (int)v.size() - 1; i >= 0; i--) h = new Node{v[i], h}; return h; }
void freeList(Node* h) { std::set<Node*> s; while (h && s.insert(h).second) h = h->next; for (Node* n : s) delete n; }

int main() {
    must_finish(5, "endless loop, or more than one pass");
    Node* m = merge(build({1, 5, 9, 20}), build({2, 4, 6, 14}));
    CHECK_EQ(toVector(m), vector<int>({1, 2, 4, 5, 6, 9, 14, 20}));
    CHECK(relinkedOnly(m));
    Node* n = merge(build({1, 4}), build({2, 3, 9}));
    CHECK_EQ(toVector(n), vector<int>({1, 2, 3, 4, 9}));
    if (submitting()) {
        CHECK(relinkedOnly(n));
        CHECK(merge(nullptr, nullptr) == nullptr);
        CHECK_EQ(toVector(merge(nullptr, build({2, 5}))), vector<int>({2, 5}));
        CHECK_EQ(toVector(merge(build({2, 5}), nullptr)), vector<int>({2, 5}));
        CHECK_EQ(toVector(merge(build({6, 8}), build({1, 2}))), vector<int>({1, 2, 6, 8}));
        CHECK_EQ(toVector(merge(build({3, 3}), build({3, 4}))), vector<int>({3, 3, 3, 4}));
        Node* w = merge(build({1, 5, 9, 20}), build({2, 50}));
        CHECK_EQ(toVector(w), vector<int>({1, 2, 5, 9, 20, 50}));
        CHECK(relinkedOnly(w));
    }
    for (auto& p : made) delete p.first;
    return check_done();
}

