    return fibonacci(n - 1) + fibonacci(n - 2);
}

int fibonacciCounted(int n, vector<int>& calls) {
    calls[n]++;
    if (n == 0 || n == 1) return 1;
    return fibonacciCounted(n - 1, calls) + fibonacciCounted(n - 2, calls);
