#include <string>
using std::string;

// ---- done in earlier lessons ----

bool isPalindromeRecursive(const string& input, int b, int e) {
    if (b >= e) return true;
    if (input[b] != input[e]) return false;
    return isPalindromeRecursive(input, b + 1, e - 1);
}

bool isPalindrome(const string& input) {
    return isPalindromeRecursive(input, 0, (int)input.length() - 1);
}

string reverse(const string& input) {
    if (input.empty()) return "";
