}

string dec_to_bin(int n) {
    if (n == 0) return "";
    return dec_to_bin(n / 2) + std::to_string(n % 2);
}

// ---- this lesson ----

bool isSubHelper(const string& s, const string& t, int sIndex, int tIndex) {
    if (sIndex == (int)s.size()) return true;
    if (tIndex == (int)t.size()) return false;
    if (s[sIndex] == t[tIndex]) return isSubHelper(s, t, sIndex + 1, tIndex + 1);
    else return isSubHelper(s, t, sIndex, tIndex + 1);
}

bool isSub(const string& s, const string& t) {
    return isSubHelper(s, t, 0, 0);
}

