#include <iostream>

struct Node {
    int elt;
    Node* next;
};

struct DNode {
    int elt;
    DNode *prev, *next;
};

// ---- done in earlier lessons ----

int findMiddle(DNode* head, DNode* tail) {
    if (head == tail || head == tail->prev) return head->elt;
    return findMiddle(head->next, tail->prev);
}

void printReverse(Node* head) {
    if (head == nullptr) return;
    printReverse(head->next);
    std::cout << head->elt << " ";
}

int countNodes(Node* head) {
    if (head == nullptr) return 0;
    return 1 + countNodes(head->next);
}

// ---- this lesson ----

Node* reverseHelper(Node* ptr, Node* last) {
    if (ptr->next == nullptr) {
        ptr->next = last;
        return ptr;     // the old tail is the new head
    }
    Node* newHead = reverseHelper(ptr->next, ptr);
    ptr->next = last;
    return newHead;
}

Node* reverse(Node* ptr) {
    if (ptr == nullptr) return ptr;
    return reverseHelper(ptr, nullptr);
}

