class FullStackException {};
class EmptyStackException {};

class UndoStack {
public:
    UndoStack(int maxSize) : list(new char[maxSize]), maxStackSize(maxSize), stackTop(0) {}
    ~UndoStack() { delete[] list; }
    UndoStack(const UndoStack&) = delete;
    UndoStack& operator=(const UndoStack&) = delete;

    int size() const { return stackTop; }
    bool isEmpty() const {
        return stackTop == 0;
    }
    bool isFull() const {
        return stackTop == maxStackSize;
    }
    void push(char e) {
        if (isFull()) throw FullStackException();
        list[stackTop++] = e;
    }
    char pop() {
        if (isEmpty()) throw EmptyStackException();
        return list[--stackTop];
    }
    char top() const {
        if (isEmpty()) throw EmptyStackException();
        return list[stackTop - 1];
    }

private:
    char* list;
    int maxStackSize;
    int stackTop;   // how many are stored, which is also the next free slot
};

