#pragma once

class EmptyStackException {};

class LinkedUndoStack {
public:
    LinkedUndoStack() : stackTop(nullptr), count(0) {}
    ~LinkedUndoStack() {
        while (stackTop) {
            Node* next = stackTop->next;
            delete stackTop;
            stackTop = next;
        }
    }
    LinkedUndoStack(const LinkedUndoStack&) = delete;
    LinkedUndoStack& operator=(const LinkedUndoStack&) = delete;

    int size() const { return count; }
    bool isEmpty() const { return stackTop == nullptr; }
    void push(char e) {
        stackTop = new Node{e, stackTop};
        count++;
    }
    char pop() {
        if (isEmpty()) throw EmptyStackException();
        Node* old = stackTop;
        char e = old->data;
        stackTop = old->next;
        delete old;
        count--;
        return e;
    }
    char top() const {
        if (isEmpty()) throw EmptyStackException();
        return stackTop->data;
    }

private:
    struct Node {
        char data;
        Node* next;
    };
    Node* stackTop;   // the head of the list
    int count;
};

