#pragma once
#include <sstream>
#include <stack>
#include <string>

int evalPostfix(const std::string& expr) {
    std::istringstream in(expr);
    std::stack<int> st;
    std::string t;
    while (in >> t) {
        if (t == "+" || t == "-" || t == "*" || t == "/") {
            int b = st.top(); st.pop();
            int a = st.top(); st.pop();
            if (t == "+") st.push(a + b);
            else if (t == "-") st.push(a - b);
            else if (t == "*") st.push(a * b);
            else st.push(a / b);
        } else {
            st.push(std::stoi(t));
        }
    }
    return st.top();
}

