class PrintQueue {
public:
    PrintQueue(int N) : Q(new int[N]), N(N), f(0), r(0) {}
    ~PrintQueue() { delete[] Q; }
    PrintQueue(const PrintQueue&) = delete;
    PrintQueue& operator=(const PrintQueue&) = delete;

