        if (isEmpty()) throw EmptyQueueException();
        int v = Q[f];
        f = (f + 1) % N;
        return v;
    }
    int front() const {
        if (isEmpty()) throw EmptyQueueException();
        return Q[f];
    }

    // ---- this lesson ----

    void grow() {
        int n = size();
        int* B = new int[2 * N];
        for (int i = 0; i < n; i++) B[i] = Q[(f + i) % N];
        delete[] Q;
        Q = B;
        N *= 2;
        f = 0;
        r = n;
    }
    void enqueue(int v) {
        if (size() == N - 1) grow();
        Q[r] = v;
        r = (r + 1) % N;
    }

private:
    int* Q;
    int N;
    int f;   // index of the front job
    int r;   // index one past the last job
