#pragma once

class FullDequeException {};
class EmptyDequeException {};

class PrintDeque {
public:
    PrintDeque(int N) : Q(new int[N]), N(N), f(0), r(0) {}
    ~PrintDeque() { delete[] Q; }
    PrintDeque(const PrintDeque&) = delete;
    PrintDeque& operator=(const PrintDeque&) = delete;

    // ---- done in earlier lessons (it's the circular queue) ----
    int size() const { return (N - f + r) % N; }
    bool isEmpty() const { return f == r; }
    void insertBack(int v) {
        if (size() == N - 1) throw FullDequeException();
        Q[r] = v;
        r = (r + 1) % N;
    }
    int removeFront() {
        if (isEmpty()) throw EmptyDequeException();
        int v = Q[f];
        f = (f + 1) % N;
        return v;
    }
    int first() const {
        if (isEmpty()) throw EmptyDequeException();
        return Q[f];
    }

    // ---- this lesson ----
    void insertFront(int v) {
        if (size() == N - 1) throw FullDequeException();
        f = (f - 1 + N) % N;
        Q[f] = v;
    }
    int removeBack() {
        if (isEmpty()) throw EmptyDequeException();
        r = (r - 1 + N) % N;
        return Q[r];
    }
    int last() const {
        if (isEmpty()) throw EmptyDequeException();
        return Q[(r - 1 + N) % N];
    }

private:
    int* Q;
    int N;
    int f;   // index of the front job
    int r;   // index one past the last job
};

