#pragma once

// ---- done in earlier lessons ----

int sequentialSearch(const int arr[], int n, int key) {
    for (int i = 0; i < n; i++)
        if (arr[i] == key) return i;
    return -1;
}

int binarySearch(const int arr[], int n, int key) {
    int first = 0, last = n - 1;
    while (first <= last) {
        int mid = first + (last - first) / 2;
        if (arr[mid] == key) return mid;
        else if (arr[mid] < key) first = mid + 1;
        else last = mid - 1;
    }
    return -1;
}

// ---- this lesson ----

int insertOrdered(int arr[], int& n, int key) {
    int first = 0, last = n - 1;
    while (first <= last) {
        int mid = first + (last - first) / 2;
        if (arr[mid] == key) return -1;
        else if (arr[mid] < key) first = mid + 1;
        else last = mid - 1;
    }
    for (int i = n; i > first; i--) arr[i] = arr[i - 1];
    arr[first] = key;
    n++;
    return first;
}

