#pragma once
#include <cstdint>
#include <string>

int foldingHash(const std::string& key, int max) {
    uint64_t sum = 0;
    for (size_t i = 0; i < key.size(); i += 4) {
        uint32_t chunk = 0;
        for (size_t j = i; j < i + 4 && j < key.size(); j++)
            chunk = (chunk << 8) | (unsigned char)key[j];
        sum += chunk;
    }
    return sum % max;
}

