#pragma once
#include <vector>
using std::vector;

struct Node {
    int key, value;
    Node* next;
};

class ChainedTable {
public:
    ChainedTable(int m) : buckets(m, nullptr) {}
    ~ChainedTable() {
        for (Node* cur : buckets)
            while (cur) {
                Node* nxt = cur->next;
                delete cur;
                cur = nxt;
            }
    }
    ChainedTable(const ChainedTable&) = delete;
    ChainedTable& operator=(const ChainedTable&) = delete;

    int chainLength(int b) const {
        int len = 0;
        for (Node* cur = buckets[b]; cur && len < 1000; cur = cur->next) len++;
        return len;
    }

    int* find(int k) {
        for (Node* cur = buckets[k % buckets.size()]; cur; cur = cur->next)
            if (cur->key == k) return &cur->value;
        return nullptr;
    }

    void insert(int k, int v) {
        if (int* old = find(k)) { *old = v; return; }
        Node*& head = buckets[k % buckets.size()];
        head = new Node{k, v, head};
    }

    bool erase(int k) {
        for (Node** link = &buckets[k % buckets.size()]; *link; link = &(*link)->next)
            if ((*link)->key == k) {
                Node* dead = *link;
                *link = dead->next;
                delete dead;
                return true;
            }
        return false;
    }

private:
    vector<Node*> buckets;
};

