    vector<int> S1(S.begin(), S.begin() + half), S2(S.begin() + half, S.end());
    return merge(mergeSort(S1), mergeSort(S2));
}

int partition(vector<int>& S, int lo, int hi) {
    int pivot = S[hi], i = lo;
    for (int j = lo; j < hi; j++)
        if (S[j] <= pivot) { std::swap(S[i], S[j]); i++; }
    std::swap(S[i], S[hi]);
    return i;
}

void quickSort(vector<int>& S, int lo, int hi) {
    if (lo >= hi) return;
    int p = partition(S, lo, hi);
    quickSort(S, lo, p - 1);
    quickSort(S, p + 1, hi);
}

// ---- this lesson ----

int randomPartition(vector<int>& S, int lo, int hi) {
    int r = lo + std::rand() % (hi - lo + 1);
    std::swap(S[r], S[hi]);
    return partition(S, lo, hi);
}

void randomQuickSort(vector<int>& S, int lo, int hi) {
    if (lo >= hi) return;
    int p = randomPartition(S, lo, hi);
    randomQuickSort(S, lo, p - 1);
    randomQuickSort(S, p + 1, hi);
}

