bool sharesNodes(TreeNode* a, TreeNode* b) {
    std::set<TreeNode*> x, y;
    collect(a, x);
    collect(b, y);
    for (TreeNode* p : y) if (x.count(p)) return true;
    return false;
}

void freeTrees(std::initializer_list<TreeNode*> roots) {   // frees each node once, even if two trees share it
    std::set<TreeNode*> all;
    for (TreeNode* r : roots) collect(r, all);
