    inorder(c, in);
    CHECK_EQ(pre, vector<int>({1, 2, 4, 5, 3, 6}));
    CHECK_EQ(in, vector<int>({4, 2, 5, 1, 3, 6}));
    CHECK(!sharesNodes(t, c));               // deep: every node is new
    if (submitting()) {
        CHECK(copyTree(nullptr) == nullptr);
        if (c != nullptr) c->info = 99;      // changing the copy...
        CHECK_EQ(t->info, 1);                // ...leaves the original alone
        TreeNode* chain = N(1, nullptr, N(2, N(3)));
        TreeNode* d = copyTree(chain);
        vector<int> dp;
        preorder(d, dp);
        CHECK_EQ(dp, vector<int>({1, 2, 3}));
        CHECK_EQ(height(d), 2);
        CHECK(!sharesNodes(chain, d));
        freeTrees({chain, d});
    }
    freeTrees({t, c});
    return check_done();
}

