        remove(v, 4); remove(v, 2); remove(v, 8); remove(v, 7); remove(v, 6); remove(v, 9);
        CHECK(v == nullptr);
        freeTree(w); freeTree(u);
    }
    freeTree(t);
    freeTree(lec);
