#include <set>
#include "check.h"
#include "bst.h"

TreeNode* N(int v, TreeNode* l = nullptr, TreeNode* r = nullptr) { return new TreeNode{v, l, r}; }

void pre(TreeNode* t, vector<int>& v) {
    if (t == nullptr || v.size() >= 40) return;     // capped, so a cycle fails instead of hanging
    v.push_back(t->info);
    pre(t->left, v);
    pre(t->right, v);
}
vector<int> shape(TreeNode* t) { vector<int> v; pre(t, v); return v; }   // pre-order pins down a BST's shape

void collect(TreeNode* t, std::set<TreeNode*>& seen) {
    if (t && seen.insert(t).second) { collect(t->left, seen); collect(t->right, seen); }
}
void freeTree(TreeNode* t) {
    std::set<TreeNode*> all;
    collect(t, all);
    for (TreeNode* p : all) delete p;
}

TreeNode* balanced(int lo, int hi) {     // a perfectly balanced BST of the even keys 2*lo .. 2*hi
    if (lo > hi) return nullptr;
    int mid = lo + (hi - lo) / 2;
    return new TreeNode{2 * mid, balanced(lo, mid - 1), balanced(mid + 1, hi)};
}

TreeNode* build(std::initializer_list<int> keys) {   // inserts in order, the same way the lesson does
    TreeNode* t = nullptr;
    for (int k : keys) {
        TreeNode** p = &t;
        while (*p) p = k < (*p)->info ? &(*p)->left : &(*p)->right;
        *p = N(k);
    }
    return t;
}

int main() {
    TreeNode* t = build({50, 30, 70, 20, 40, 60, 80, 10, 25, 35, 45, 90});
    vector<int> a;
    range(t, 35, 62, a);
    CHECK_EQ(a, vector<int>({35, 40, 45, 50, 60}));
    vector<int> b;
    range(t, 0, 100, b);
    CHECK_EQ(b, vector<int>({10, 20, 25, 30, 35, 40, 45, 50, 60, 70, 80, 90}));
    if (submitting()) {
        vector<int> c;
        range(t, 51, 59, c);
        CHECK(c.empty());
        vector<int> d;
        range(t, 90, 90, d);
        CHECK_EQ(d, vector<int>({90}));
        vector<int> e;
        range(t, 10, 25, e);
        CHECK_EQ(e, vector<int>({10, 20, 25}));
        vector<int> f;
        range(nullptr, 0, 10, f);
        CHECK(f.empty());
        TreeNode* big = balanced(0, 131070);     // even keys 0 .. 262140
        long total = 0;
        must_finish(3, "skip the subtrees that can't hold a key in range");
        for (int i = 0; i < 20000; i++) {
            int j = i % 5000;
            vector<int> out;
            range(big, 50 * j + 1, 50 * j + 20, out);
            total += out.size();
        }
        must_finish(0);
        CHECK_EQ(total, 20000L * 10);
        freeTree(big);
    }
    freeTree(t);
    return check_done();
}

