vector<string> keys(const vector<NameEntry>& v) {
    vector<string> k;
    for (const NameEntry& e : v) k.push_back(e.key);
    return k;
}

void freeNames(NameNode* t, int depth = 0) {
    if (t == nullptr || depth > 100) return;
    freeNames(t->left, depth + 1);
    freeNames(t->right, depth + 1);
    delete t;
}

vector<string> suggest(NameNode* t, const string& prefix, int limit) {
    vector<NameEntry> out;
    startingWith(t, prefix, out, limit);
    return keys(out);
}

void addBalanced(NameNode*& t, int lo, int hi) {   // keys "b00000" .. in a balanced order
    if (lo > hi) return;
    int mid = lo + (hi - lo) / 2;
    char buf[16];
    std::snprintf(buf, sizeof buf, "b%05d", mid);
    insert(t, NameEntry{buf, 100 + mid});
    addBalanced(t, lo, mid - 1);
    addBalanced(t, mid + 1, hi);
}

int main() {
    NameNode* t = nullptr;
    vector<NameEntry> all = {
        {"student union", 6}, {"eng", 0}, {"campus village b", 3}, {"sci", 1}, {"music building", 9},
        {"campus village 2", 5}, {"su", 6}, {"science building", 1}, {"art building", 8},
        {"campus village a", 2}, {"engineering building", 0}, {"swc", 7}, {"campus village c", 4},
        {"student wellness center", 7}, {"mus", 9}, {"art", 8}, {"spartan gym", 10}};
    for (const NameEntry& e : all) insert(t, e);
    CHECK_EQ(suggest(t, "campus v", 10), vector<string>({"campus village 2", "campus village a", "campus village b", "campus village c"}));
    CHECK_EQ(suggest(t, "Campus V", 2), vector<string>({"campus village 2", "campus village a"}));
