        CHECK_EQ(suggest(t, "s", 10), vector<string>({"sci", "spartan gym", "student union", "student wellness center"}));
        CHECK_EQ(suggest(t, "s", 2), vector<string>({"sci", "spartan gym"}));
        CHECK_EQ(suggest(t, "art", 5), vector<string>({"art"}));
        CHECK_EQ(suggest(t, "zzz", 5), vector<string>());
        CHECK_EQ(suggest(t, "music building!", 5), vector<string>());
        CHECK_EQ(suggest(t, "campus", 0), vector<string>());
        CHECK_EQ(suggest(nullptr, "a", 5), vector<string>());
        vector<NameEntry> one;
        startingWith(t, "student w", one, 5);
        CHECK(one.size() == 1 && one[0].buildingId == 7);

        NameNode* big = nullptr;
