    int buildingId;
    bool operator<(const NameEntry& o) const {
        if (key != o.key) return key < o.key;
        return buildingId < o.buildingId;   // same name: lower id first
    }
    bool operator==(const NameEntry& o) const { return key == o.key && buildingId == o.buildingId; }
};

struct NameNode {
    NameEntry info;
    NameNode* left;
    NameNode* right;
};

// ---- given ----
void insert(NameNode*& root, const NameEntry& e) {
    NameNode** p = &root;
    while (*p != nullptr) {
        if (e < (*p)->info) p = &(*p)->left;
        else if ((*p)->info < e) p = &(*p)->right;
        else return;
    }
    *p = new NameNode{e, nullptr, nullptr};
}

string lowercase(string s) {
    for (char& c : s) c = std::tolower((unsigned char)c);
    return s;
}

bool startsWith(const string& s, const string& prefix) { return s.compare(0, prefix.size(), prefix) == 0; }

// ---- this lesson ----
bool hasBuilding(const vector<NameEntry>& out, int id) {
    for (const NameEntry& e : out)
        if (e.buildingId == id) return true;
    return false;
}

void collect(NameNode* t, const string& p, vector<NameEntry>& out, int limit) {
    if (t == nullptr || (int)out.size() >= limit) return;
    const string& k = t->info.key;
    if (startsWith(k, p)) {
        collect(t->left, p, out, limit);
        if ((int)out.size() < limit && !hasBuilding(out, t->info.buildingId)) out.push_back(t->info);
        collect(t->right, p, out, limit);
    } else if (k < p) {
        collect(t->right, p, out, limit);
    } else {
        collect(t->left, p, out, limit);
    }
}

void startingWith(NameNode* t, const string& prefix, vector<NameEntry>& out, int limit) {
    collect(t, lowercase(prefix), out, limit);
}

