#pragma once
#include <stdexcept>
#include <utility>
#include <vector>
using std::vector;

class MinHeap {
public:
    bool empty() const { return A.empty(); }
    int size() const { return A.size(); }

    void push(int key) {
        A.push_back(key);
        int i = A.size() - 1;
        while (i > 0 && A[i] < A[(i - 1) / 2]) {
            std::swap(A[i], A[(i - 1) / 2]);
            i = (i - 1) / 2;
        }
    }

    int top() const {
        if (A.empty()) throw std::runtime_error("empty heap");
        return A[0];
    }

    int pop() {
        int min = top();
        A[0] = A.back();
        A.pop_back();
        int i = 0, n = A.size();
        while (true) {
            int s = i, l = 2 * i + 1, r = 2 * i + 2;
            if (l < n && A[l] < A[s]) s = l;
            if (r < n && A[r] < A[s]) s = r;
            if (s == i) break;
            std::swap(A[i], A[s]);
            i = s;
        }
        return min;
    }

private:
    vector<int> A;
};

