#pragma once
#include <functional>
#include <queue>
#include <vector>
using std::vector;

vector<int> mostUrgentFirst(const vector<int>& scores) {
    std::priority_queue<int> pq(scores.begin(), scores.end());
    vector<int> out;
    while (!pq.empty()) { out.push_back(pq.top()); pq.pop(); }
    return out;
}

vector<int> leastUrgentFirst(const vector<int>& scores) {
    std::priority_queue<int, vector<int>, std::greater<int>> pq(scores.begin(), scores.end());
    vector<int> out;
    while (!pq.empty()) { out.push_back(pq.top()); pq.pop(); }
    return out;
}

