    vector<int> dist(adj.size(), -1);
    std::queue<int> q;
    dist[s] = 0;
    q.push(s);
    while (!q.empty()) {
        int v = q.front();
        q.pop();
        for (int w : adj[v])
            if (dist[w] == -1) {
                dist[w] = dist[v] + 1;
                q.push(w);
            }
    }
    return dist;
}

vector<int> fewestHopsPath(const vector<vector<int>>& adj, int s, int t) {
    vector<int> parent(adj.size(), -1);
    vector<bool> visited(adj.size(), false);
    std::queue<int> q;
    visited[s] = true;
    q.push(s);
    while (!q.empty()) {
        int v = q.front();
        q.pop();
        for (int w : adj[v])
            if (!visited[w]) {
                visited[w] = true;
                parent[w] = v;
                q.push(w);
            }
    }
    if (!visited[t]) return {};
    vector<int> path;
    for (int v = t; v != -1; v = parent[v]) path.push_back(v);
    std::reverse(path.begin(), path.end());
    return path;
}

