struct Path {
    bool found = false;
    long long length = 0;
    vector<int> vertices;
};

Path closestRoute(const vector<vector<Edge>>& adj, const vector<int>& sources, const vector<int>& targets) {
    using P = std::pair<long long, int>;
    int n = adj.size();
    vector<long long> dist(n, INF);
    vector<int> prev(n, -1);
    vector<bool> finished(n, false), isTarget(n, false);
    for (int t : targets) isTarget[t] = true;
    std::priority_queue<P, vector<P>, std::greater<P>> pq;
    for (int s : sources) {
        dist[s] = 0;
        pq.push({0, s});
    }
    while (!pq.empty()) {
        auto [d, u] = pq.top();
        pq.pop();
        if (finished[u]) continue;
        finished[u] = true;
        if (isTarget[u]) {
            Path p;
            p.found = true;
            p.length = dist[u];
            for (int v = u; v != -1; v = prev[v]) p.vertices.push_back(v);
            std::reverse(p.vertices.begin(), p.vertices.end());
            return p;
        }
        for (auto [v, len] : adj[u])
            if (dist[u] + len < dist[v]) {
                dist[v] = dist[u] + len;
                prev[v] = u;
                pq.push({dist[v], v});
            }
    }
    return {};
}

