long long fibMemo(int n, std::unordered_map<int, long long>& memo) {
    if (n <= 1) return 1;                   // f(0) = f(1) = 1
    if (memo.count(n)) return memo[n];      // cache hit
    memo[n] = fibMemo(n - 1, memo) + fibMemo(n - 2, memo);
    return memo[n];
}

long long fib(int n) {
    std::unordered_map<int, long long> memo;
    return fibMemo(n, memo);
}

long long fibTable(int n) {
    vector<long long> f(n + 1, 1);          // f[0] = f[1] = 1
    for (int i = 2; i <= n; i++) f[i] = f[i - 1] + f[i - 2];
    return f[n];
}

int rodCut(const vector<int>& price, int n) {
    vector<int> best(n + 1, 0);
    for (int j = 1; j <= n; j++)
        for (int i = 1; i <= j; i++)
            best[j] = std::max(best[j], price[i] + best[j - i]);
    return best[n];
}

vector<int> bestCuts(const vector<int>& price, int n) {
    vector<int> best(n + 1, 0), first(n + 1, 0);
    for (int j = 1; j <= n; j++)
        for (int i = 1; i <= j; i++)
            if (price[i] + best[j - i] > best[j]) {
                best[j] = price[i] + best[j - i];
                first[j] = i;
            }
    vector<int> pieces;
    for (int j = n; j > 0; j -= first[j]) pieces.push_back(first[j]);
    return pieces;
}

int knapsack(const vector<int>& weight, const vector<int>& value, int W) {
    int n = weight.size();
    vector<vector<int>> best(n + 1, vector<int>(W + 1, 0));   // row 0: no items
    for (int i = 1; i <= n; i++)
        for (int w = 0; w <= W; w++) {
            best[i][w] = best[i - 1][w];                       // skip item i
            if (weight[i - 1] <= w)                            // take it, if it fits
                best[i][w] = std::max(best[i][w], value[i - 1] + best[i - 1][w - weight[i - 1]]);
        }
    return best[n][W];
}

